import type { Destination, MonthClimate } from "./types";

// Helper para escribir clima más compacto. high/low en °C, rain en mm/mes.
const c = (high: number, low: number, rain: number, sea?: number): MonthClimate =>
  sea !== undefined ? { highC: high, lowC: low, rainMm: rain, seaTempC: sea } : { highC: high, lowC: low, rainMm: rain };

